from collections import defaultdict, deque

class RateLimiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.events = defaultdict(deque)

    def allow(self, timestamp, key):
        dq = self.events[key]
        # Remove events that are outside the sliding window
        # The window is (timestamp - window, timestamp]
        # So we need to remove events with time <= timestamp - window
        while dq and dq[0] <= timestamp - self.window:
            dq.popleft()

        if len(dq) < self.limit:
            dq.append(timestamp)
            return True
        else:
            return False
```

